<xf:if is="$group.group_id == 'wutime_snowstorm_options'">
	<xf:js>
		(function() {
			var themeInputs = document.querySelectorAll('input[name="options[wutime_snowstorm_option_theme]"]');
			var scopeInputs = document.querySelectorAll('input[name="options[wutime_snowstorm_display_scope]"]');
			var scheduleInputs = document.querySelectorAll('input[name="options[wutime_snowstorm_schedule_enable]"]');
			if (!themeInputs.length) {
				return;
			}

			function findRow(optionId) {
				var anchor = document.getElementById(optionId);
				if (!anchor) {
					return null;
				}

				var row = anchor.nextElementSibling;
				while (row && !row.classList.contains('formRow')) {
					row = row.nextElementSibling;
				}

				return row;
			}

			var rows = {
				snowMobile: findRow('wutime_snowstorm_show_mobile_snow'),
				snowStormMobile: findRow('wutime_snowstorm_show_mobile'),
				snowStormJs: findRow('wutime_snowstorm_js_customizations'),
				snowflakeMobile: findRow('wutime_snowstorm_show_mobile_snowflake'),
				snowflakeJs: findRow('wutime_snowstorm_js_customizations_snowflake'),
				scheduleStart: findRow('wutime_snowstorm_schedule_start'),
				scheduleEnd: findRow('wutime_snowstorm_schedule_end'),
				scopeIncludeForums: findRow('wutime_snowstorm_scope_forums_include'),
				scopeExcludeForums: findRow('wutime_snowstorm_scope_forums_exclude')
			};

			function selectedTheme() {
				for (var i = 0; i < themeInputs.length; i++) {
					if (themeInputs[i].checked) {
						return themeInputs[i].value;
					}
				}
				return '';
			}

			function selectedScope() {
				for (var i = 0; i < scopeInputs.length; i++) {
					if (scopeInputs[i].checked) {
						return scopeInputs[i].value;
					}
				}
				return 'everywhere';
			}

			function scheduleEnabled() {
				for (var i = 0; i < scheduleInputs.length; i++) {
					if (scheduleInputs[i].checked) {
						return scheduleInputs[i].value !== '0';
					}
				}
				return false;
			}

			function setVisible(row, visible) {
				if (!row) {
					return;
				}
				row.style.display = visible ? '' : 'none';
			}

			function syncRows() {
				var theme = selectedTheme();
				setVisible(rows.snowMobile, theme === 'Snow');
				setVisible(rows.snowStormMobile, theme === 'Default');
				setVisible(rows.snowStormJs, theme === 'Default');
				setVisible(rows.snowflakeMobile, theme === 'Snowflake');
				setVisible(rows.snowflakeJs, theme === 'Snowflake');

				var isScheduled = scheduleEnabled();
				setVisible(rows.scheduleStart, isScheduled);
				setVisible(rows.scheduleEnd, isScheduled);

				var scope = selectedScope();
				setVisible(rows.scopeIncludeForums, scope === 'selected_forums_only');
				setVisible(rows.scopeExcludeForums, scope === 'selected_forums_exclude');
			}

			for (var i = 0; i < themeInputs.length; i++) {
				themeInputs[i].addEventListener('change', syncRows);
			}
			for (var i = 0; i < scopeInputs.length; i++) {
				scopeInputs[i].addEventListener('change', syncRows);
			}
			for (var i = 0; i < scheduleInputs.length; i++) {
				scheduleInputs[i].addEventListener('change', syncRows);
			}

			syncRows();
		}());
	</xf:js>

	<xf:if is="$xf.options.wutime_snowstorm_preview_on_options_page">
		<xf:set var="$wutimeSnowIsMobile" value="{{ wutime_snowstorm_is_mobile() }}" />

		<xf:if is="$xf.options.wutime_snowstorm_option_theme == 'Default'">
			<xf:if is="$xf.options.wutime_snowstorm_show_mobile OR !$wutimeSnowIsMobile">
				<xf:js addon="Wutime/SnowStorm" src="wutime/snowstorm/snowstorm.js" defer="true" min="1" />
				<xf:js>{{$xf.options.wutime_snowstorm_js_customizations}}</xf:js>
			</xf:if>
		<xf:elseif is="$xf.options.wutime_snowstorm_option_theme == 'Snowflake'" />
			<xf:if is="$xf.options.wutime_snowstorm_show_mobile_snowflake OR !$wutimeSnowIsMobile">
				<xf:js>window.SnowflakeConfig = window.SnowflakeConfig || {};
{{$xf.options.wutime_snowstorm_js_customizations_snowflake}}</xf:js>
				<xf:js addon="Wutime/SnowStorm" src="wutime/snowstorm/snowflake.js" defer="true" min="1" />
			</xf:if>
		<xf:else />
			<xf:if is="$xf.options.wutime_snowstorm_show_mobile_snow OR !$wutimeSnowIsMobile">
				<xf:js addon="Wutime/SnowStorm" src="wutime/snowstorm/snow.js" defer="true" min="1" />
			</xf:if>
		</xf:if>
	</xf:if>
</xf:if>
